-- Seed A2 Unit 2: Organizar la vida diaria y hacer planes.
insert into public.course_units(course_id,title,description,learning_objectives,sequence,is_published)
values ('71dc9833-bd13-4262-b7be-be1889b81c3f'::uuid,'Organizar la vida diaria y hacer planes','Talk about routines, upcoming plans, responsibilities, and making arrangements with other people.','["Describe daily routines using reflexive verbs and frequency expressions","Talk about future plans with ir a + infinitive","Express obligations and advice with tener que, hay que, and deber","Make, accept, and decline invitations using natural conversational chunks"]'::jsonb,2,true)
on conflict(course_id,sequence) do update set title=excluded.title,description=excluded.description,learning_objectives=excluded.learning_objectives,is_published=true;

insert into public.lessons(unit_id,slug,title,description,lesson_type,estimated_minutes,sequence,learning_objectives,content,points_reward,is_published)
select u.id,v.slug,v.title,v.description,v.lesson_type,v.estimated_minutes,v.sequence,v.learning_objectives,v.content,v.points_reward,true
from public.course_units u cross join (values
('describir-tu-rutina-diaria','Describe your daily routine','Use reflexive verbs and frequency expressions to explain how your day is organized.','core',30,5,'["Identify common reflexive verbs in everyday routines","Place reflexive pronouns correctly with conjugated verbs","Conjugate common routine verbs in the present","Describe a routine in a connected sequence"]'::jsonb,'{"sections":[{"body":"People often make small talk by asking what a normal day looks like. To answer naturally, you need reflexive verbs such as levantarse, ducharse, and acostarse, plus expressions that show how often something happens. Today you will build a clear description of your routine rather than translate isolated verbs.","type":"intro","title":"Describe your daily routine","eyebrow":"01 · COMMUNICATIVE GOAL"},{"note":"Learn each infinitive with its reflexive pronoun (se). When you use it in a sentence, the pronoun changes to match the subject: me, te, se, nos, se.","type":"vocabulary","items":[{"term":"despertarse","example":"Me despierto a las seis y media.","meaning":"to wake up"},{"term":"levantarse","example":"Me levanto después de apagar la alarma.","meaning":"to get up"},{"term":"ducharse","example":"Me ducho por la mañana.","meaning":"to shower"},{"term":"vestirse","example":"Me visto antes de desayunar.","meaning":"to get dressed"},{"term":"acostarse","example":"Me acuesto antes de las once.","meaning":"to go to bed"},{"term":"por lo general","example":"Por lo general, desayuno en casa.","meaning":"generally"},{"term":"casi siempre","example":"Casi siempre camino al trabajo.","meaning":"almost always"},{"term":"de vez en cuando","example":"De vez en cuando preparo algo especial.","meaning":"from time to time"}],"title":"The language of a normal day","eyebrow":"02 · USEFUL CHUNKS"},{"text":"Entre semana me despierto a las seis y cuarto. Primero, me levanto y abro las ventanas. Después me ducho y me visto. Normalmente desayuno en casa, pero los martes y jueves compro café cerca del trabajo. Empiezo a trabajar a las ocho y hago una pausa a mediodía. Por la tarde, regreso a casa, preparo la cena y ordeno un poco. No siempre hago ejercicio, pero casi siempre salgo a caminar. Me acuesto alrededor de las diez y media porque quiero descansar bien.","type":"reading","title":"Un día entre semana","eyebrow":"03 · READ FOR MEANING","glossary":[["entre semana","during the week"],["me despierto","I wake up"],["me levanto","I get up"],["me visto","I get dressed"],["hago una pausa","I take a break"],["regreso","I return"],["alrededor de","around"],["me acuesto","I go to bed"]],"instructions":"Read aloud twice. On the second reading, underline the reflexive pronouns and notice where they appear."},{"body":"A reflexive verb describes an action the subject does to or for themselves. The infinitive ends in -se (levantarse). With a conjugated verb, remove -se and place the matching pronoun before the verb: yo me levanto, tú te levantas, ella se levanta.","note":"With two verbs, the pronoun can go before the conjugated verb or attach to the infinitive: Me voy a acostar temprano = Voy a acostarme temprano. Both are correct. Do not leave the infinitive ending in -se after adding the pronoun.","type":"grammar","steps":["Find the subject: yo, tú, ella, nosotros, or ellos.","Choose the matching pronoun: me, te, se, nos, se.","Conjugate the verb for the subject.","Add a time or frequency phrase to make the routine specific."],"table":{"rows":[["yo","me","me levanto"],["tú","te","te levantas"],["él / ella / usted","se","se levanta"],["nosotros","nos","nos levantamos"],["ellos / ustedes","se","se levantan"]],"columns":["Subject","Pronoun","Form"],"heading":"Present tense: levantarse"},"title":"Reflexive pronouns and verb position","eyebrow":"04 · GRAMMAR IN CONTEXT","pattern":"SUBJECT + REFLEXIVE PRONOUN + CONJUGATED VERB","examples":[["Me despierto a las seis.","I wake up at six."],["Mi hermana se viste rápido.","My sister gets dressed quickly."],["Nos acostamos tarde los viernes.","We go to bed late on Fridays."]],"patternExample":"Yo + me + levanto + a las seis y media."},{"type":"practice","title":"Build accurate routine sentences","eyebrow":"05 · GUIDED RETRIEVAL","questions":[{"rule":"él / ella → se","retry":"Mi hermana _____ levanta temprano.","answer":"se","prompt":"Mi hermano _____ despierta a las siete.","options":["me","te","se"],"explanation":"Mi hermano is third-person singular. The reflexive pronoun is se: se despierta.","retryAnswer":"se"},{"rule":"nosotros → nos","retry":"Nosotros _____ duchamos por la mañana.","answer":"nos","prompt":"Nosotros _____ acostamos después de las diez.","options":["nos","se","te"],"explanation":"The subject nosotros requires nos. The verb is nos acostamos.","retryAnswer":"nos"},{"rule":"yo → me","retry":"Yo _____ despierto a las seis.","answer":"me","prompt":"Yo _____ visto antes de desayunar.","options":["me","se","nos"],"explanation":"For yo, use me: me visto. Vestirse also changes e to i in the stem.","retryAnswer":"me"},{"rule":"acostarse + a las + time","retry":"Complete: Normalmente _____ levanto a las siete.","answer":"Normalmente me acuesto a las once.","prompt":"Which sentence means “I usually go to bed at eleven”?","options":["Normalmente me acuesto a las once.","Normalmente se acuesta a las once.","Normalmente me acuesto las once."],"explanation":"Me acuesto matches yo. Use a las before a clock time.","retryAnswer":"me"},{"rule":"Pronoun before conjugated verb or attached to infinitive","retry":"Choose the correct alternative: “I''m going to shower.”","answer":"Me voy a vestir.","prompt":"Choose the correct placement: “I am going to get dressed.”","options":["Me voy a vestir.","Me voy vestir se.","Voy a me vestir."],"explanation":"Me voy a vestir is correct. You could also say Voy a vestirme.","retryAnswer":"Voy a ducharme"}],"instructions":"Choose the pronoun and verb form that agree with the subject."},{"type":"production","model":"Entre semana me despierto a las seis y me levanto poco después. Me ducho, me visto y preparo el desayuno. Normalmente empiezo a trabajar a las ocho. A mediodía hago una pausa y como algo. Por la tarde regreso a casa y salgo a caminar. Casi siempre me acuesto antes de las once.","title":"Explain your weekday routine","eyebrow":"06 · INDEPENDENT PRODUCTION","prompts":["What time do you wake up and get up?","What do you do before work or school?","What happens during the day?","What do you do in the evening?","What time do you go to bed?"],"checklist":["I used at least five reflexive verbs.","My pronouns match the subject.","I included at least three frequency or time expressions.","My sentences are connected in a logical order."],"instructions":"Write 6–8 sentences about a typical weekday. Include specific times and frequency expressions. Read your routine aloud twice."},{"type":"assessment","title":"Use reflexive verbs naturally","eyebrow":"07 · MASTERY CHECK","questions":[{"rule":"tú → te","retry":"Tú _____ duchas por la mañana.","answer":"te","prompt":"Tú _____ levantas muy temprano.","options":["te","se","me"],"explanation":"The subject tú takes te: te levantas.","retryAnswer":"te"},{"rule":"ellos → se","retry":"Mis amigos _____ despiertan a las ocho.","answer":"se","prompt":"Mis padres _____ acuestan tarde.","options":["nos","se","te"],"explanation":"Mis padres is plural third person, so use se: se acuestan.","retryAnswer":"se"},{"rule":"yo → me","retry":"Yo _____ acuesto a las diez.","answer":"me","prompt":"Yo _____ visto después de ducharme.","options":["me","se","nos"],"explanation":"Use me with yo. The correct form is me visto.","retryAnswer":"me"},{"rule":"nosotros → nos + levantamos","retry":"Complete: _____ despertamos temprano.","answer":"Nos levantamos a las siete.","prompt":"Which is correct for “We get up at seven”?","options":["Nos levantamos a las siete.","Se levantamos a las siete.","Nos levantan a las siete."],"explanation":"Nosotros takes nos, and the verb form is levantamos.","retryAnswer":"Nos"},{"rule":"Pronoun before conjugated verb or attached to infinitive","retry":"Choose the correct pair: “I''m going to get up.”","answer":"Me voy a acostar / Voy a acostarme","prompt":"Which two placements are correct?","options":["Me voy a acostar / Voy a acostarme","Me voy acostar / Voy me a acostar","Voy a me acostar / Me voy acostarme"],"explanation":"Both placements are accepted: before the conjugated verb or attached to the infinitive.","retryAnswer":"Me voy a levantar / Voy a levantarme"}],"instructions":"Choose the correct form and pronoun. You need at least 4 out of 5 to pass."}],"objective":"Describe a typical day with reflexive verbs, time expressions, and frequency phrases.","estimatedMinutes":30}'::jsonb,30),
('hablar-de-planes-futuros','Talk about your plans','Use ir a + infinitive to explain intentions, arrangements, and upcoming activities.','core',30,6,'["Conjugate ir in the present","Build ir a + infinitive accurately","Distinguish intentions from fixed schedules","Ask and answer questions about upcoming plans"]'::jsonb,'{"sections":[{"body":"A common conversation question is ¿Qué vas a hacer este fin de semana? Spanish often uses ir a + infinitive to talk about intentions and planned actions. You do not need a new future-tense conjugation for every verb: conjugate ir, add a, then keep the second verb in the infinitive.","type":"intro","title":"Talk about your plans","eyebrow":"01 · COMMUNICATIVE GOAL"},{"note":"Keep the whole phrase together: voy a + infinitive. Add a time phrase to show when the plan will happen.","type":"vocabulary","items":[{"term":"este fin de semana","example":"Este fin de semana voy a descansar.","meaning":"this weekend"},{"term":"la próxima semana","example":"La próxima semana vamos a viajar.","meaning":"next week"},{"term":"tener planes","example":"¿Tienes planes para el sábado?","meaning":"to have plans"},{"term":"quedarse en casa","example":"Voy a quedarme en casa.","meaning":"to stay home"},{"term":"salir a cenar","example":"Vamos a salir a cenar.","meaning":"to go out to dinner"},{"term":"hacer una reservación","example":"Voy a hacer una reservación.","meaning":"to make a reservation"},{"term":"todavía no sé","example":"Todavía no sé qué voy a hacer.","meaning":"I don''t know yet"},{"term":"quizás / tal vez","example":"Tal vez voy a visitar a mi familia.","meaning":"perhaps / maybe"}],"title":"Make your plans specific","eyebrow":"02 · PLAN-MAKING CHUNKS"},{"text":"Este sábado voy a tener un día ocupado. Por la mañana voy a hacer ejercicio y después voy a comprar algunas cosas para la casa. Mi hermana va a venir a visitarme alrededor del mediodía. Vamos a preparar el almuerzo y luego vamos a ver una película. Por la tarde, mis amigos van a jugar fútbol en el parque. Si termino mis pendientes temprano, voy a reunirme con ellos. Todavía no sé qué vamos a hacer por la noche, pero probablemente vamos a pedir comida.","type":"reading","title":"Planes para el sábado","eyebrow":"03 · READ FOR INTENTION","glossary":[["voy a tener","I''m going to have"],["voy a hacer","I''m going to do"],["va a venir","she is going to come"],["vamos a preparar","we are going to prepare"],["van a jugar","they are going to play"],["si termino","if I finish"],["pendientes","errands / things to do"],["pedir comida","to order food"]],"instructions":"Read aloud twice. Find each example of ir a + infinitive and identify the person making the plan."},{"body":"Conjugate ir in the present, add a, and use the infinitive for the planned action. Only ir changes: voy a estudiar, vas a salir, vamos a comer.","note":"Do not conjugate both verbs. “Voy a estudio” is incorrect because estudiar must stay in the infinitive. For a fixed timetable or published schedule, the present tense can also refer to the future: El tren sale a las ocho.","type":"grammar","steps":["Choose the subject.","Conjugate ir: voy, vas, va, vamos, van.","Add a.","Keep the action verb in the infinitive."],"table":{"rows":[["yo","voy","voy a + infinitive"],["tú","vas","vas a + infinitive"],["él / ella / usted","va","va a + infinitive"],["nosotros","vamos","vamos a + infinitive"],["ellos / ustedes","van","van a + infinitive"]],"columns":["Subject","Ir","Plan pattern"],"heading":"Ir in the present"},"title":"Ir a + infinitive","eyebrow":"04 · BUILD THE FUTURE PLAN","pattern":"SUBJECT + IR (PRESENT) + A + INFINITIVE","examples":[["Voy a llamar a mi mamá.","I''m going to call my mom."],["¿Qué vas a hacer mañana?","What are you going to do tomorrow?"],["Vamos a visitar a unos amigos.","We''re going to visit some friends."],["Ellos van a llegar más tarde.","They''re going to arrive later."]],"patternExample":"Nosotros + vamos + a + preparar + la cena."},{"type":"practice","title":"Build a plan","eyebrow":"05 · GUIDED RETRIEVAL","questions":[{"rule":"yo → voy","retry":"Esta tarde yo _____ a cocinar.","answer":"voy","prompt":"Mañana yo _____ a estudiar en la biblioteca.","options":["voy","vas","va"],"explanation":"The subject is yo, so ir becomes voy: voy a estudiar.","retryAnswer":"voy"},{"rule":"tú → vas","retry":"¿Adónde _____ a ir tú mañana?","answer":"vas","prompt":"¿Qué _____ a hacer tú el sábado?","options":["vas","va","vamos"],"explanation":"The subject tú takes vas: ¿Qué vas a hacer?","retryAnswer":"vas"},{"rule":"ellos → van","retry":"Mis padres _____ a venir el domingo.","answer":"van","prompt":"Mis amigos _____ a viajar en diciembre.","options":["va","van","vamos"],"explanation":"Mis amigos is plural, so use van: van a viajar.","retryAnswer":"van"},{"rule":"ir + a + infinitive","retry":"Complete: Vamos a _____ (comer) temprano.","answer":"Vamos a preparar la cena.","prompt":"Choose the correct sentence.","options":["Vamos a preparar la cena.","Vamos a preparamos la cena.","Vamos preparar a la cena."],"explanation":"Only ir is conjugated. Preparar stays in the infinitive after a.","retryAnswer":"comer"},{"rule":"Pronoun can attach to the infinitive","retry":"Complete: Voy a _____ (acostarse) temprano.","answer":"Voy a quedarme en casa.","prompt":"Which phrase means “I''m going to stay home”?","options":["Voy a quedarme en casa.","Voy quedo en casa.","Voy a me quedo en casa."],"explanation":"With a reflexive infinitive, attach me to quedarme, or say Me voy a quedar en casa.","retryAnswer":"acostarme"}],"instructions":"Choose the correct form. Pay attention to the subject and keep the second verb in the infinitive."},{"type":"production","model":"Mañana voy a levantarme temprano y voy a trabajar desde casa. Por la tarde voy a hacer ejercicio. El viernes voy a cenar con unos amigos. El sábado vamos a visitar un mercado y después vamos a tomar café. El domingo voy a descansar y preparar la semana. Todavía no sé qué voy a hacer el lunes por la noche.","title":"Plan your next seven days","eyebrow":"06 · INDEPENDENT PRODUCTION","prompts":["What are you going to do tomorrow?","What are you doing this weekend?","Who are you going to see?","What are you going to do if your plans change?","What are you not going to do?"],"checklist":["I used ir a + infinitive at least six times.","I conjugated ir to match each subject.","I kept the second verb in the infinitive.","I included time expressions."],"instructions":"Write 7–9 sentences about your real or imagined plans for the next week. Include at least one plan for work or study, one social plan, and one personal activity. Read aloud twice."},{"type":"assessment","title":"Talk about upcoming plans","eyebrow":"07 · MASTERY CHECK","questions":[{"rule":"nosotros → vamos","retry":"Nosotros _____ a visitar a Ana.","answer":"vamos","prompt":"Nosotros _____ a salir después del trabajo.","options":["vamos","van","voy"],"explanation":"The subject nosotros takes vamos: vamos a salir.","retryAnswer":"vamos"},{"rule":"The second verb stays in the infinitive","retry":"Ella va a _____ (comprar) los boletos.","answer":"hacer","prompt":"Ella va a _____ una reservación.","options":["hacer","hace","haciendo"],"explanation":"After va a, use the infinitive hacer.","retryAnswer":"comprar"},{"rule":"ustedes → van","retry":"¿Adónde _____ a ir ustedes?","answer":"van","prompt":"¿Qué _____ a hacer ustedes mañana?","options":["van","vas","vamos"],"explanation":"Ustedes takes van: ¿Qué van a hacer?","retryAnswer":"van"},{"rule":"ir + a + infinitive","retry":"Complete: Voy a _____ (leer) esta noche.","answer":"Voy a llamar después.","prompt":"Choose the correct sentence.","options":["Voy a llamar después.","Voy llamo después.","Voy a llamo después."],"explanation":"Llamar remains in the infinitive after voy a.","retryAnswer":"leer"},{"rule":"todavía no sé = I still don''t know","retry":"Translate the meaning: “Todavía no sé qué voy a comprar.”","answer":"I still don''t know what I''m going to do.","prompt":"What does “Todavía no sé qué voy a hacer” mean?","options":["I already know what I did.","I still don''t know what I''m going to do.","I never do anything."],"explanation":"The phrase expresses uncertainty about a future plan.","retryAnswer":"I still don''t know what I''m going to buy"}],"instructions":"Choose the correct structure. You need at least 4 out of 5 to pass."}],"objective":"Describe upcoming plans clearly using ir a + infinitive and time expressions.","estimatedMinutes":30}'::jsonb,30),
('expresar-obligaciones-y-consejos','Explain what you have to do','Use tener que, hay que, and deber to express personal obligations, general requirements, and advice.','core',35,7,'["Distinguish personal obligations from general requirements","Build tener que + infinitive and hay que + infinitive","Use deber + infinitive to give advice","Explain responsibilities in everyday situations"]'::jsonb,'{"sections":[{"body":"Daily conversations often involve responsibilities: what you need to finish, what people are supposed to do, and what someone should do. Spanish uses several common structures. Tener que usually identifies a specific person''s obligation; hay que expresses a general requirement; deber often gives advice or expresses duty.","type":"intro","title":"Explain what you have to do","eyebrow":"01 · COMMUNICATIVE GOAL"},{"note":"Keep the structure with the infinitive. The verb after que does not change: tengo que trabajar, tenemos que salir, hay que estudiar.","type":"vocabulary","items":[{"term":"tener que + infinitive","example":"Tengo que terminar un informe.","meaning":"to have to"},{"term":"hay que + infinitive","example":"Hay que llegar a tiempo.","meaning":"one must / it is necessary to"},{"term":"deber + infinitive","example":"Debes descansar más.","meaning":"should / ought to"},{"term":"es necesario","example":"Es necesario traer identificación.","meaning":"it is necessary"},{"term":"ser responsable de","example":"Soy responsable de organizar la reunión.","meaning":"to be responsible for"},{"term":"entregar a tiempo","example":"Tenemos que entregar el proyecto hoy.","meaning":"to turn in on time"},{"term":"tener cuidado","example":"Debes tener cuidado al cruzar.","meaning":"to be careful"},{"term":"hacer una lista","example":"Tengo que hacer una lista de pendientes.","meaning":"to make a list"}],"title":"Talk about everyday responsibilities","eyebrow":"02 · RESPONSIBILITY CHUNKS"},{"text":"Esta semana tengo muchas cosas que hacer. El lunes tengo que entregar un informe y el martes debo asistir a una reunión. También hay que preparar una presentación para el viernes. Mi compañero y yo tenemos que revisar los datos y hablar con el equipo. Para trabajar mejor, debemos organizar las tareas y tomar descansos cortos. En la oficina hay que mantener los espacios limpios y apagar las luces al salir. Si queremos terminar a tiempo, tenemos que planear bien la semana.","type":"reading","title":"Una semana con muchas responsabilidades","eyebrow":"03 · READ FOR PURPOSE","glossary":[["tengo que entregar","I have to submit"],["debo asistir","I should / must attend"],["hay que preparar","it is necessary to prepare"],["revisar los datos","to review the data"],["tomar descansos","to take breaks"],["mantener limpio","to keep clean"],["al salir","when leaving"],["a tiempo","on time"]],"instructions":"Read aloud twice. Identify which sentences describe one person''s responsibility and which describe a general rule or recommendation."},{"body":"Tener que + infinitive expresses an obligation linked to a subject: Tengo que llamar. Hay que + infinitive is impersonal and expresses what is necessary in general: Hay que respetar las reglas. Deber + infinitive commonly gives advice or expresses duty: Debes dormir más.","note":"Hay que does not change to match a person. Do not say “yo hay que”. For a personal obligation, use tengo que. Deber is stronger than a casual suggestion in some contexts, but it is often used for advice.","type":"grammar","steps":["Ask whether the obligation belongs to a specific person or is general.","Use tener que when the subject is clear.","Use hay que for an impersonal requirement.","Use deber for advice or a sense of duty.","Keep the action verb in the infinitive."],"table":{"rows":[["tener que + infinitive","A specific person or group","Tenemos que estudiar."],["hay que + infinitive","General / impersonal","Hay que estudiar."],["deber + infinitive","Advice or duty","Debes estudiar."]],"columns":["Structure","Who / what?","Example"],"heading":"Choose the structure by purpose"},"title":"Tener que, hay que, and deber","eyebrow":"04 · THREE WAYS TO EXPRESS OBLIGATION","pattern":"TENER QUE + INFINITIVE · DEBER + INFINITIVE · HAY QUE + INFINITIVE","examples":[["Tengo que llamar al médico.","I have to call the doctor."],["Hay que apagar el teléfono aquí.","You have to turn off the phone here."],["Debes hablar con tu profesor.","You should talk to your teacher."],["Tenemos que salir temprano.","We have to leave early."]],"patternExample":"Yo + tengo + que + terminar el trabajo."},{"type":"practice","title":"Choose the right obligation","eyebrow":"05 · GUIDED RETRIEVAL","questions":[{"rule":"yo → tengo que + infinitive","retry":"Yo _____ que terminar este trabajo.","answer":"tengo","prompt":"Yo _____ que estudiar para el examen.","options":["tengo","hay","debo que"],"explanation":"A personal obligation with yo uses tengo que estudiar.","retryAnswer":"tengo"},{"rule":"General rule → hay que + infinitive","retry":"En un hospital _____ respetar a los pacientes.","answer":"hay que","prompt":"En esta biblioteca _____ hablar en voz baja.","options":["hay que","tengo que","debo que"],"explanation":"This is a general requirement for everyone in the library. Use hay que.","retryAnswer":"hay que"},{"rule":"Advice → deber + infinitive","retry":"Si te duele la cabeza, _____ tomar agua.","answer":"debes","prompt":"Si estás cansado, _____ descansar.","options":["debes","hay","tienes"],"explanation":"Debes descansar gives advice to tú. Do not add que after deber.","retryAnswer":"debes"},{"rule":"ellos → tienen que","retry":"Mis amigos _____ que trabajar mañana.","answer":"tienen","prompt":"Mis compañeros _____ que llegar a las nueve.","options":["tiene","tenemos","tienen"],"explanation":"Mis compañeros is plural, so use tienen que llegar.","retryAnswer":"tienen"},{"rule":"hay que has no personal subject","retry":"Choose the impersonal rule: “_____ pagar antes de entrar.”","answer":"Hay que llevar identificación.","prompt":"Which sentence is impersonal?","options":["Hay que llevar identificación.","Tengo que llevar identificación.","Debes llevar identificación."],"explanation":"Hay que states a general requirement without naming who must do it.","retryAnswer":"Hay que"}],"instructions":"Choose the structure that fits the meaning and subject."},{"type":"production","model":"Esta semana tengo que terminar dos proyectos y llamar a un cliente. En casa, tenemos que comprar comida y limpiar la cocina. En mi trabajo hay que llegar a tiempo y respetar las reuniones. Si alguien tiene mucho trabajo, debe organizar sus prioridades y tomar descansos. También debemos pedir ayuda cuando sea necesario.","title":"Explain your responsibilities","eyebrow":"06 · INDEPENDENT PRODUCTION","prompts":["What do you personally have to do this week?","What does everyone need to do in a shared place?","What advice would you give someone who is busy?","What happens if people do not meet their responsibilities?"],"checklist":["I used tener que for personal obligations.","I used hay que for at least one general requirement.","I used deber to give advice.","The action verbs after these structures remain infinitives."],"instructions":"Write 7–9 sentences about responsibilities in your work, studies, home, or community. Include personal obligations, general rules, and advice. Read aloud twice."},{"type":"assessment","title":"Express obligation and advice","eyebrow":"07 · MASTERY CHECK","questions":[{"rule":"ella → tiene que","retry":"Mi padre _____ que salir temprano.","answer":"tiene","prompt":"Mi hermana _____ que trabajar el sábado.","options":["tiene","hay","debe que"],"explanation":"Mi hermana is ella, so use tiene que trabajar.","retryAnswer":"tiene"},{"rule":"General rule → hay que","retry":"_____ que lavarse las manos antes de cocinar.","answer":"Hay","prompt":"_____ que usar casco en esta zona.","options":["Hay","Tengo","Debo"],"explanation":"This is an impersonal safety requirement: Hay que usar casco.","retryAnswer":"Hay"},{"rule":"deber + infinitive","retry":"Debes _____ (dormir) más.","answer":"beber","prompt":"Debes _____ más agua durante el día.","options":["beber","bebes","bebiendo"],"explanation":"The verb after debes remains in the infinitive: beber.","retryAnswer":"dormir"},{"rule":"nosotros → tenemos que","retry":"Nosotros _____ que estudiar para el examen.","answer":"tenemos","prompt":"Nosotros _____ que preparar la presentación.","options":["tenemos","tienen","hay"],"explanation":"Nosotros takes tenemos: tenemos que preparar.","retryAnswer":"tenemos"},{"rule":"deber + infinitive commonly gives advice","retry":"Choose the advice: “You should take a break.”","answer":"Debes hablar con ella.","prompt":"Which sentence gives advice?","options":["Debes hablar con ella.","Hay que cerrar la puerta.","Tengo que cerrar la puerta."],"explanation":"Debes hablar con ella recommends an action to tú.","retryAnswer":"Debes tomar un descanso"}],"instructions":"Choose the structure that communicates the intended meaning. You need at least 4 out of 5 to pass."}],"objective":"Explain responsibilities and give practical advice using three common obligation structures.","estimatedMinutes":35}'::jsonb,35),
('hacer-planes-e-invitaciones','Make plans and invitations','Invite people, respond naturally, and arrange a time using poder, querer, and everyday conversational phrases.','core',35,8,'["Use ¿Quieres...? and ¿Te gustaría...? to invite someone","Use poder to ask about availability","Accept, decline, and suggest alternatives politely","Confirm arrangements with time and place details"]'::jsonb,'{"sections":[{"body":"Knowing grammar is useful, but conversation also depends on social language. You need to invite someone, find out whether they are available, accept or decline politely, and suggest another time. This lesson gives you practical phrases for making plans without sounding abrupt.","type":"intro","title":"Make plans and invitations","eyebrow":"01 · COMMUNICATIVE GOAL"},{"note":"Learn these as complete phrases. A natural response often includes a reason or an alternative, not just sí or no.","type":"vocabulary","items":[{"term":"¿Quieres salir?","example":"¿Quieres salir a cenar el viernes?","meaning":"Do you want to go out?"},{"term":"¿Te gustaría...?","example":"¿Te gustaría ir al cine?","meaning":"Would you like...?"},{"term":"¿Puedes...?","example":"¿Puedes venir a las siete?","meaning":"Can you...?"},{"term":"¡Claro que sí!","example":"¡Claro que sí! Me encantaría.","meaning":"Of course!"},{"term":"Me encantaría, pero...","example":"Me encantaría, pero tengo que trabajar.","meaning":"I''d love to, but..."},{"term":"¿Qué tal si...?","example":"¿Qué tal si nos vemos el sábado?","meaning":"How about if...?"},{"term":"A esa hora no puedo.","example":"A esa hora no puedo, pero puedo más tarde.","meaning":"I can''t at that time."},{"term":"Quedamos a las...","example":"Quedamos a las ocho en la entrada.","meaning":"Let''s meet at..."}],"title":"Invite, accept, and suggest","eyebrow":"02 · CONVERSATION CHUNKS"},{"text":"Marta: ¿Quieres ir a cenar el viernes? Luis: ¡Me encantaría! ¿A qué hora? Marta: ¿Puedes llegar a las siete y media? Luis: A esa hora no puedo porque tengo que terminar un proyecto. ¿Qué tal a las ocho y media? Marta: Perfecto. ¿Te gustaría probar el restaurante nuevo del centro? Luis: Claro que sí. ¿Hacemos una reservación? Marta: Buena idea. Yo puedo llamar. Entonces, quedamos a las ocho y media en la entrada. Luis: ¡Nos vemos el viernes!","type":"reading","title":"Un plan para el viernes","eyebrow":"03 · READ THE CONVERSATION","glossary":[["me encantaría","I''d love to"],["¿a qué hora?","at what time?"],["a esa hora","at that time"],["¿qué tal...?","how about...?"],["buena idea","good idea"],["hacer una reservación","to make a reservation"],["quedamos","we''ll meet / let''s meet"],["nos vemos","see you"]],"instructions":"Read the dialogue aloud twice, switching roles. Notice how the speakers invite, decline politely, and offer an alternative."},{"body":"Use querer to ask what someone wants to do: ¿Quieres ir? Use poder to check availability or ability: ¿Puedes venir? Use the conditional phrase ¿Te gustaría...? to make a softer, more polite invitation. You can respond with me encantaría, claro, or a polite decline plus an alternative.","note":"After querer, poder, and gustaría, use an infinitive: ¿Quieres comer? ¿Puedes venir? ¿Te gustaría salir? Avoid conjugating the second verb.","type":"grammar","steps":["Make the invitation with querer or te gustaría.","Check availability with poder if needed.","Accept or decline politely.","Offer another time or activity if the first plan does not work.","Confirm the time and place."],"table":{"rows":[["Direct invitation","¿Quieres + infinitive?","¿Quieres tomar un café?"],["Polite invitation","¿Te gustaría + infinitive?","¿Te gustaría cenar?"],["Check availability","¿Puedes + infinitive?","¿Puedes venir mañana?"],["Suggest an alternative","¿Qué tal si + present?","¿Qué tal si nos vemos el sábado?"]],"columns":["Purpose","Spanish pattern","Example"],"heading":"Useful invitation patterns"},"title":"Querer, poder, and gustaría","eyebrow":"04 · POLITE REQUESTS AND RESPONSES","pattern":"INVITATION + RESPONSE + ALTERNATIVE + CONFIRMATION","examples":[["Me encantaría, pero trabajo hasta tarde.","I''d love to, but I work until late."],["A esa hora no puedo.","I can''t at that time."],["¿Qué tal a las ocho?","How about at eight?"],["Quedamos en la entrada.","Let''s meet at the entrance."]],"patternExample":"¿Quieres salir? → Me encantaría, pero... → ¿Qué tal el sábado? → Perfecto, quedamos a las seis."},{"type":"practice","title":"Respond naturally","eyebrow":"05 · GUIDED RETRIEVAL","questions":[{"rule":"¿Te gustaría + infinitive","retry":"Invite someone for coffee: ¿Te gustaría _____ un café?","answer":"¿Te gustaría ir al cine?","prompt":"You want to invite a friend to the movies. Which is natural?","options":["¿Te gustaría ir al cine?","¿Te gustaría vas al cine?","¿Te gustaría fuiste al cine?"],"explanation":"After te gustaría, use the infinitive ir.","retryAnswer":"tomar"},{"rule":"Decline + offer an alternative","retry":"Complete politely: A esa hora no puedo, pero _____ el sábado.","answer":"A esa hora no puedo, pero puedo más tarde.","prompt":"Your friend asks if you can come at seven. You are busy. What is a polite response?","options":["A esa hora no puedo, pero puedo más tarde.","No.","No puedo tú."],"explanation":"A natural response gives the reason or an alternative rather than stopping at no.","retryAnswer":"puedo"},{"rule":"querer + infinitive","retry":"¿Quieres _____ conmigo? (venir)","answer":"¿Quieres salir a cenar?","prompt":"Choose the correct invitation.","options":["¿Quieres salir a cenar?","¿Quieres sales a cenar?","¿Quieres saliste a cenar?"],"explanation":"The verb after quieres stays in the infinitive: salir.","retryAnswer":"venir"},{"rule":"me encantaría + pero + tener que + infinitive","retry":"Complete: Me encantaría, pero _____ que estudiar.","answer":"Me encantaría, pero tengo que trabajar.","prompt":"How do you say “I''d love to, but I have to work”?","options":["Me encantaría, pero tengo que trabajar.","Me encanta, pero tengo trabajar.","Me gustaría, pero trabajo que."],"explanation":"Me encantaría is a polite positive response. Tengo que trabajar explains why you cannot accept.","retryAnswer":"tengo"},{"rule":"quedamos a las + time","retry":"Confirm: Quedamos _____ las seis.","answer":"Quedamos a las ocho.","prompt":"Which phrase confirms a meeting time?","options":["Quedamos a las ocho.","A veces a las ocho.","Quiero ocho."],"explanation":"Quedamos a las ocho confirms the agreed meeting time.","retryAnswer":"a"}],"instructions":"Choose the phrase that best fits the conversational situation."},{"type":"production","model":"Ana: ¿Te gustaría ir al mercado el sábado? Diego: ¡Me encantaría! ¿A qué hora? Ana: ¿Puedes llegar a las diez? Diego: A esa hora no puedo porque tengo una clase. ¿Qué tal a las once y media? Ana: Perfecto. Podemos tomar café después. Diego: ¡Buena idea! Entonces, quedamos a las once y media en la entrada. Ana: ¡Nos vemos!","title":"Arrange a real plan","eyebrow":"06 · ROLE-PLAY PRODUCTION","prompts":["What is the invitation?","How does the other person respond?","What prevents the first time from working?","What alternative do they suggest?","What time and place do they confirm?"],"checklist":["I used ¿Quieres...? or ¿Te gustaría...?","I used poder to check availability.","I included a polite decline or acceptance.","I confirmed the final time and place."],"instructions":"Write a short 8–10 line dialogue between two friends. One person invites the other to do something. The other person cannot make the first time, so they negotiate an alternative and confirm the plan. Read both roles aloud."},{"type":"assessment","title":"Make and confirm an invitation","eyebrow":"07 · MASTERY CHECK","questions":[{"rule":"¿Te gustaría + infinitive","retry":"¿Te gustaría _____ a cenar? (venir)","answer":"¿Te gustaría venir conmigo?","prompt":"Which is the most polite invitation?","options":["¿Te gustaría venir conmigo?","¿Te gustaría vienes conmigo?","¿Vienes gustaría conmigo?"],"explanation":"The infinitive venir follows te gustaría.","retryAnswer":"venir"},{"rule":"Decline the time + suggest an alternative","retry":"Suggest eight instead: ¿Qué tal _____ las ocho?","answer":"A las seis no puedo. ¿Qué tal a las siete?","prompt":"You cannot meet at six, but seven works. What do you say?","options":["A las seis no puedo. ¿Qué tal a las siete?","No puedo seis siete.","A las siete ayer."],"explanation":"This response clearly states the problem and offers another time.","retryAnswer":"a"},{"rule":"poder conjugated + infinitive","retry":"¿_____ venir el viernes? (tú)","answer":"¿Puedes venir mañana?","prompt":"Choose the correct phrase: “Can you come tomorrow?”","options":["¿Puedes venir mañana?","¿Puedes vienes mañana?","¿Poder venir mañana?"],"explanation":"Puedes is conjugated for tú; venir stays in the infinitive.","retryAnswer":"Puedes"},{"rule":"Accept positively with a natural chunk","retry":"Complete the acceptance: ¡Claro que sí! Me _____.","answer":"¡Claro que sí! Me encantaría.","prompt":"Which response accepts an invitation warmly?","options":["¡Claro que sí! Me encantaría.","A esa hora no puedo.","Todavía no sé ayer."],"explanation":"Claro que sí and me encantaría are warm, natural ways to accept.","retryAnswer":"encantaría"},{"rule":"quedamos + time + place confirms an arrangement","retry":"Translate the arrangement: “Quedamos a las seis en el café.”","answer":"Let''s meet at eight at the entrance.","prompt":"What does “Quedamos a las ocho en la entrada” mean?","options":["We met yesterday at eight.","Let''s meet at eight at the entrance.","We have eight entrances."],"explanation":"Quedamos confirms the agreed meeting time and place.","retryAnswer":"Let''s meet at six at the cafe"}],"instructions":"Choose the most natural conversational response. You need at least 4 out of 5 to pass."}],"objective":"Invite someone, respond politely, and settle on a practical arrangement in Spanish.","estimatedMinutes":35}'::jsonb,35)
